Lemma append_growA : forall (LB : list (Z * Z)) (FF LK : list fframe) (cr : credit) (A : list (Z * Z)) (o cap p q sp r : Z) (s src : list Z),
  PMSA.cps_asan L ar HI 989840 r sp PMSA.STR_SCR LB FF LK cr A 0
      (fun R M => 1 <= Z.of_nat (length src) /\ (cap <= Z.of_nat (length s) + Z.of_nat (length src) <= 2 * cap - 2) /\ PMSA.a0 R o /\ PMSA.a1 R q /\ PMSA.a2 R (Z.of_nat (length src)) /\
                  PMSA.str_at L M o (PML.SLong cap p s) /\ 24 <= cap /\ In (p, cap) LB /\ shadow_blk M p cap /\ PMSA.fobj M FF o 24 /\ PMSA.stksh ar M sp PMSA.STR_SCR /\
                  PMSA.str_src_ok L M LB p q src /\ Z.of_nat (length s) + Z.of_nat (length src) < 2 ^ 26 /\ acredit_ok L cr (PML.grow_cap cap (Z.of_nat (length s) + Z.of_nat (length src))))
      (fun R M R' M' LB' cr' LBk W => exists p', let cap' := PML.grow_cap cap (Z.of_nat (length s) + Z.of_nat (length src)) in
